using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace RogControl {
 public partial class MainWindow {
  WindowsDisplayController windowsDisplayController;
  WindowsDisplaySnapshot windowsDisplay;
  WindowsDisplayRestorePoint windowsDisplayUndo;
  readonly Dictionary<string,uint> windowsDisplayDraft=new Dictionary<string,uint>(StringComparer.Ordinal);
  string windowsDisplayMessage="";
  void InitializeWindowsDisplay(){windowsDisplayController=new WindowsDisplayController(new WindowsDisplayNativeApi(()=>{hardwareControlPolicy.Demand();if(render||closing&&!windowsSystemWriting)throw new InvalidOperationException("显示设置操作已结束。");}));}
  void OriginalWindowsDisplayPage(){
   Header("屏幕设置","");var commands=new WrapPanel{Margin=new Thickness(0,0,0,18)};var read=Button(busy?"正在读取…":"刷新",async()=>await ReadWindowsDisplay());read.IsEnabled=!busy&&!closing&&!render;commands.Children.Add(read);commands.Children.Add(Button("返回工具",()=>ShowPage("工具")));content.Children.Add(commands);
   if(windowsDisplay!=null)foreach(var screen in windowsDisplay.Screens){var current=screen;var box=Box(screen.Name+(screen.Primary?" · 主显示器":""),"");var mode=screen.CurrentMode;
    if(mode!=null&&mode.Valid){box.Children.Add(Paragraph(mode.Width+" × "+mode.Height+" · "+mode.ReportedRefreshRateHz+" Hz",17,text));if(mode.TargetRefreshRateHz.HasValue)box.Children.Add(Paragraph("时序刷新率："+mode.TargetRefreshRateHz.Value.ToString("0.###",CultureInfo.InvariantCulture)+" Hz",12,muted));}
    uint selectedRate=NormalizeWindowsDisplayDraft(screen);var rates=new ComboBox{Width=220,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,8,0,12),IsEnabled=!busy&&screen.ManualRefreshSupported};foreach(uint rate in screen.SupportedReportedRefreshRatesHz){var item=new ComboBoxItem{Content=rate+" Hz",Tag=rate};rates.Items.Add(item);if(selectedRate==rate)rates.SelectedItem=item;}
    rates.SelectionChanged+=(s,e)=>{var item=rates.SelectedItem as ComboBoxItem;if(!busy&&item!=null)windowsDisplayDraft[current.Id]=(uint)item.Tag;};box.Children.Add(rates);var apply=Button("应用刷新率",async()=>await ChangeWindowsDisplay(current),true);apply.IsEnabled=HardwareWritesEnabled&&!busy&&screen.ManualRefreshSupported&&windowsDisplayUndo==null;box.Children.Add(apply);
    if(!String.IsNullOrEmpty(screen.Error)){var state=Paragraph("设置不可用",12,muted);state.ToolTip=screen.Error;box.Children.Add(state);}content.Children.Add(Card(box));
   }
   if(windowsDisplayUndo!=null){var undo=Row();var restore=Button("恢复修改前的刷新率",async()=>await RestoreWindowsDisplay());restore.IsEnabled=HardwareWritesEnabled&&!busy;undo.Children.Add(restore);var keep=Button("保留当前刷新率",()=>{windowsDisplayUndo=null;windowsDisplayMessage="已保留当前刷新率。";ShowPage(page);});keep.IsEnabled=!busy;undo.Children.Add(keep);content.Children.Add(undo);}
   if(!String.IsNullOrEmpty(windowsDisplayMessage))content.Children.Add(Paragraph(windowsDisplayMessage,13,muted));
  }
  uint NormalizeWindowsDisplayDraft(WindowsDisplayScreen screen){uint draft;if(windowsDisplayDraft.TryGetValue(screen.Id,out draft)&&screen.SupportedReportedRefreshRatesHz.Contains(draft))return draft;draft=screen.CurrentMode!=null&&screen.SupportedReportedRefreshRatesHz.Contains(screen.CurrentMode.ReportedRefreshRateHz)?screen.CurrentMode.ReportedRefreshRateHz:screen.SupportedReportedRefreshRatesHz.FirstOrDefault();windowsDisplayDraft[screen.Id]=draft;return draft;}
  void SetWindowsDisplayRead(WindowsDisplaySnapshot snapshot){windowsDisplay=snapshot;if(snapshot==null){windowsDisplayDraft.Clear();return;}var present=new HashSet<string>(snapshot.Screens.Select(s=>s.Id),StringComparer.Ordinal);foreach(string id in windowsDisplayDraft.Keys.ToArray())if(!present.Contains(id))windowsDisplayDraft.Remove(id);foreach(var screen in snapshot.Screens)NormalizeWindowsDisplayDraft(screen);}
  async Task ReadWindowsDisplay(){if(busy||closing||render)return;busy=true;ShowPage(page);try{var task=Task.Run(()=>windowsDisplayController.Read());windowsSystemTask=task;var snapshot=await task;if(!closing){SetWindowsDisplayRead(snapshot);windowsDisplayMessage=snapshot.Screens.Count==0?"未识别到已连接屏幕。":"";if(snapshot.Warnings.Count>0)windowsDisplayMessage=String.Join("；",snapshot.Warnings);}}catch(Exception ex){windowsDisplay=null;windowsDisplayMessage="读取失败："+ex.Message;}finally{windowsSystemTask=null;busy=false;if(!closing)ShowPage(page);}}
  async Task ChangeWindowsDisplay(WindowsDisplayScreen screen){if(busy||closing||render||screen==null||windowsDisplayUndo!=null)return;if(!PermitHardwareWrite())return;uint rate;if(!windowsDisplayDraft.TryGetValue(screen.Id,out rate))return;busy=true;windowsSystemWriting=true;ShowPage(page);try{var task=Task.Run(()=>windowsDisplayController.ApplyRefreshRate(screen,rate,true));windowsSystemTask=task;WindowsDisplayChanged(await task);}catch(Exception ex){windowsDisplayMessage="应用失败："+ex.Message;}finally{windowsSystemWriting=false;windowsSystemTask=null;busy=false;if(!closing)ShowPage(page);}}
  async Task RestoreWindowsDisplay(){if(busy||closing||render||windowsDisplayUndo==null)return;if(!PermitHardwareWrite())return;var point=windowsDisplayUndo;busy=true;windowsSystemWriting=true;ShowPage(page);try{var task=Task.Run(()=>windowsDisplayController.Restore(point,true));windowsSystemTask=task;var result=await task;WindowsDisplayChanged(result);if(result.ReadbackConfirmed){windowsDisplayUndo=null;windowsDisplayMessage="原刷新率已读回。";if(result.OriginalTargetTimingRestored==false)windowsDisplayMessage+=" 驱动报告的精确时序与原值不同。";}}catch(Exception ex){windowsDisplayMessage="恢复失败："+ex.Message;}finally{windowsSystemWriting=false;windowsSystemTask=null;busy=false;if(!closing)ShowPage(page);}}
  void WindowsDisplayChanged(WindowsDisplayChangeResult result){if(result==null){SetWindowsDisplayRead(null);windowsDisplayMessage="应用未确认：未返回显示设置结果。";return;}if(result.ObservedScreen!=null&&windowsDisplay!=null){var screens=windowsDisplay.Screens.Select(screen=>screen.Id==result.ObservedScreen.Id?result.ObservedScreen:screen).ToList();windowsDisplayDraft.Remove(result.ObservedScreen.Id);SetWindowsDisplayRead(new WindowsDisplaySnapshot{Screens=new System.Collections.ObjectModel.ReadOnlyCollection<WindowsDisplayScreen>(screens),Warnings=windowsDisplay.Warnings,CapturedAtUtc=DateTime.UtcNow});}else if(result.ObservedScreen==null)SetWindowsDisplayRead(null);if(result.RestorePoint!=null)windowsDisplayUndo=result.RestorePoint;windowsDisplayMessage=result.AlreadyCurrent?"刷新率相同，无需修改。":result.ReadbackConfirmed?"刷新率已读回。":"应用未确认："+result.Error;}
 }
}
